import { MeshBasicNodeMaterial, PlaneGeometry } from 'three/webgpu';
import { uv, vec3, mix, Fn, uniform, float, vec2, sin, cos, dot, length, step, fract, floor, abs } from 'three/tsl';
import { gsap } from 'gsap';
import { createText } from '@/text'; // not used directly, via ctx.fontAtlas

export default function createNode(config, ctx) {
  const group = new ctx.THREE.Group();

  // --- Extract text content ---
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textItem = items.find(item => item.role === 'headline') || items[0];
  const text = textItem?.text ?? 'Features 2';
  const fontSize = textItem?.typography?.fontSize ?? 39;
  const color = '#e8ecf2'; // paper

  // --- Create text ---
  const textMesh = ctx.fontAtlas.createText(text, {
    fontSize,
    color,
    align: 'center',
  });
  // Compute bounding box to size the plane
  textMesh.traverse(child => {
    if (child.isMesh) {
      child.geometry.computeBoundingBox();
      child.geometry.computeBoundingSphere();
    }
  });
  const textWidth = textMesh.children[0]?.geometry?.boundingBox?.max.x - textMesh.children[0]?.geometry?.boundingBox?.min.x || 2.0;
  const textHeight = textMesh.children[0]?.geometry?.boundingBox?.max.y - textMesh.children[0]?.geometry?.boundingBox?.min.y || 0.3;
  const padding = 0.3;
  const planeWidth = textWidth + padding * 2;
  const planeHeight = textHeight + padding * 1.5;

  // --- Create plane with gradient + grain ---
  const planeGeo = new PlaneGeometry(planeWidth, planeHeight);
  // Build gradient material using TSL
  const surfaceColor = vec3(0.043, 0.043, 0.062); // #0b0b10
  const inkColor = vec3(0.086, 0.086, 0.122); // #16161d
  const accentColor = vec3(1.0, 0.165, 0.22); // #ff2a38

  // Gradient: vertical from surface to slightly lighter
  const gradient = Fn(() => {
    const u = uv();
    // Vertical gradient
    const t = float(u.y).mul(0.6).add(0.2); // 0.2..0.8 range
    const base = mix(surfaceColor, inkColor, t);
    // Subtle grain using hash of uv
    const hash = Fn(() => {
      const p = vec2(u.x.mul(20.0), u.y.mul(20.0));
      const a = vec2(127.1, 311.7);
      const b = vec2(269.5, 183.3);
      const c = dot(p, a);
      const d = dot(p, b);
      const e = fract(sin(c).add(cos(d)).mul(43758.5453));
      return e;
    })();
    const grain = hash.mul(0.03).sub(0.015); // ±0.015
    const finalColor = base.add(vec3(grain, grain, grain));
    return vec3(finalColor);
  });

  const material = new MeshBasicNodeMaterial();
  material.colorNode = gradient();

  const plane = new ctx.THREE.Mesh(planeGeo, material);
  plane.position.z = -0.01; // behind text
  group.add(plane);

  // --- Position text ---
  textMesh.position.set(0, 0, 0.01);
  group.add(textMesh);

  // --- No interactions ---
  group.userData.handlers = {};

  // --- Cleanup ---
  group.userData.cleanup = () => {
    planeGeo.dispose();
    material.dispose();
    textMesh.traverse(child => {
      if (child.isMesh) {
        child.geometry.dispose();
        if (child.material) child.material.dispose();
      }
    });
  };

  return group;
}
